from tools.mcptester.mcptester.scenarios.base import BaseScenario, TestCase

class BindersScenario(BaseScenario):
    name = 'binders'
    description = 'Binder management tools'

    def get_test_cases(self) -> list[TestCase]:
        return [TestCase(name='list_binders_default', tool='list_binders', params={}, expected={'is_array': True, 'error': False, 'array_length_range': [3, 3], 'all_items_keys': ['id', 'investigation_id', 'status', 'created_at']}, description='List binders returns all 3 fixture binders'), TestCase(name='list_binders_active', tool='list_binders', params={'status': 'active'}, expected={'is_array': True, 'error': False, 'array_length_range': [1, 1], 'all_items_field_equals': {'status': 'active'}}, description='List only active binders returns 1'), TestCase(name='list_binders_archived', tool='list_binders', params={'status': 'archived'}, expected={'is_array': True, 'error': False, 'array_length_range': [1, 1], 'all_items_field_equals': {'status': 'archived'}}, description='List only archived binders returns 1'), TestCase(name='list_binders_completed', tool='list_binders', params={'status': 'completed'}, expected={'is_array': True, 'error': False, 'array_length_range': [1, 1], 'all_items_field_equals': {'status': 'completed'}}, description='List only completed binders returns 1'), TestCase(name='list_binders_limit', tool='list_binders', params={'limit': 2}, expected={'is_array': True, 'error': False, 'array_length_range': [1, 2]}, description='List binders with limit 2'), TestCase(name='get_binder_existing', tool='get_binder', params={'binder_id': 'binder_001'}, expected={'exact_values': {'id': 'binder_001', 'investigation_id': 'inv_001'}, 'contains_keys': ['status', 'created_at']}, description='Get existing binder returns correct data'), TestCase(name='get_binder_not_found', tool='get_binder', params={'binder_id': 'nonexistent_binder_id'}, expected={'contains_keys': ['error']}, description='Get non-existent binder returns error'), TestCase(name='get_binder_summary_not_found', tool='get_binder_summary', params={'investigation_id': 'nonexistent_inv_id'}, expected={'contains_keys': ['error']}, description='Get summary for non-existent investigation returns error'), TestCase(name='list_binders_invalid_status', tool='list_binders', params={'status': 'invalid_status'}, expected={'is_array': True, 'error': False}, description='List binders with invalid status returns empty array'), TestCase(name='list_binders_zero_limit', tool='list_binders', params={'limit': 0}, expected={'is_array': True, 'error': False}, description='List binders with zero limit')]